#include <string>
#include <vector>

class Solution {
public:
    int minTimeToActivate(std::string s, std::vector<int>& order, int k) {
        int n = s.size();
        auto check = [&](int time) {
            std::vector<bool> active(n, false);
            for (int t = 0; t < time; ++t) {
                active[order[t]] = true;
            }
            int consecutive = 0;
            for (int i = 0; i < n; ++i) {
                if (!active[i]) {
                    consecutive++;
                    if (consecutive >= k) return false;
                } else {
                    consecutive = 0;
                }
            }
            return true;
        };

        int low = 1, high = order.size(), ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (check(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int minTimeToActivate(String s, int[] order, int k) {
        int n = s.length();
        int low = 1, high = order.length, ans = high;

        while (low <= high) {
            int mid = (low + high) >>> 1;
            if (isValid(n, order, k, mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private boolean isValid(int n, int[] order, int k, int time) {
        boolean[] active = new boolean[n];
        for (int t = 0; t < time; t++) {
            active[order[t]] = true;
        }
        int consecutive = 0;
        for (int i = 0; i < n; i++) {
            if (!active[i]) {
                consecutive++;
                if (consecutive >= k) return false;
            } else {
                consecutive = 0;
            }
        }
        return true;
    }
}

